package com.nigson.acceptance.fulfillment;
import com.nigson.acceptance.cart.CartFixture;
import com.nigson.commerce.fulfillment.*;
import com.nigson.commerce.inventory.InventoryAuthority;
import com.nigson.commerce.platform.*;
import com.nigson.shared.security.ActorAssertion;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.transaction.support.TransactionTemplate;
import org.junit.jupiter.api.*;
import java.util.*;
import java.time.*;
import static org.assertj.core.api.Assertions.*;
class DeliveryRulePersistenceTest {
 CartFixture fixture;DeliveryRuleService service;JdbcDeliveryRules repository;ActorAssertion.Actor operations;
 @BeforeEach void setup(){String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null,"fulfillment-check supplies isolated PostgreSQL");if(!url.matches("jdbc:postgresql://127.0.0.1:[0-9]+/nigson"))throw new IllegalArgumentException("LOCAL_TEST_DB_REQUIRED");var ds=new DriverManagerDataSource(url+"?currentSchema=commerce","nigson_commerce_app","mock-commerce-runtime");fixture=new CartFixture(new JdbcTemplate(ds),new DataSourceTransactionManager(ds));var f=fixture.f;f.jdbc.update("INSERT INTO commerce.staff_role_assignment(id,created_by,updated_by,party_id,role,granted_by) VALUES (?,'test','test',?,'OPERATIONS',?)",UUID.randomUUID(),f.customer.party(),f.finance.party());operations=new ActorAssertion.Actor(f.customer.party(),f.customer.identityIssuer(),f.customer.identitySubject(),null,Set.of("CUSTOMER","OPERATIONS"),Set.of(),Instant.now());Clock clock=Clock.systemUTC();repository=new JdbcDeliveryRules(f.jdbc,clock);service=new DeliveryRuleService(repository,new InventoryAuthority(f.jdbc),f.jdbc,new PlatformStore(f.jdbc,f.manager,clock,f.metrics),new AuditWriter(f.jdbc,clock,f.metrics),f.metrics);}
 @AfterEach void cleanup(){if(fixture!=null){fixture.f.jdbc.update("DELETE FROM commerce.delivery_rule WHERE market_id=?",fixture.f.market);fixture.f.jdbc.update("DELETE FROM commerce.staff_role_assignment WHERE party_id=? AND role='OPERATIONS'",operations.party());fixture.close();}}
 private FulfillmentValues.RuleInput input(String region,String postal,int priority,String fee,String free){return new FulfillmentValues.RuleInput(fixture.f.market,"NG",region,postal,fee,free,priority,true);}
 private DeliveryRules.Fee resolve(String region,String postal,String subtotal){return new TransactionTemplate(fixture.f.manager).execute(s->repository.resolve(fixture.f.market,"NG",region,postal,new java.math.BigDecimal(subtotal)));}
 @Test void approvedCoverageSpecificityFreeThresholdAndRevisionAreCurrent(){var broad=service.create(operations,input(null,null,100,"12.34",null),"broad",UUID.randomUUID());var regional=service.create(operations,input("SYNTH_REGION",null,-100,"5.00","100.00"),"region",UUID.randomUUID());assertThat(resolve("SYNTH_REGION",null,"99.99").ruleId()).isEqualTo(regional.id());assertThat(resolve("SYNTH_REGION",null,"99.99").amount()).isEqualTo("5.00");assertThat(resolve("SYNTH_REGION",null,"100.00").amount()).isEqualTo("0.00");assertThat(resolve("OTHER_REGION",null,"100.00").ruleId()).isEqualTo(broad.id());var update=input("SYNTH_REGION",null,-100,"6.00",null);var changed=service.update(operations,regional.id(),0,update,"update",UUID.randomUUID());assertThat(changed.version()).isEqualTo(1);assertThat(service.update(operations,regional.id(),0,update,"update",UUID.randomUUID())).isEqualTo(changed);assertThat(resolve("SYNTH_REGION",null,"100.00").amount()).isEqualTo("6.00");assertThatThrownBy(()->service.update(operations,regional.id(),0,update,"stale",UUID.randomUUID())).hasMessage("VERSION_MISMATCH");assertThatThrownBy(()->service.create(operations,input(null,null,100,"0.00",null),"ambiguous",UUID.randomUUID())).hasMessage("FULFILLMENT_RULE_VIOLATION");}
 @Test void currentRoleAndCoverageGuardBothWritesAndReplay(){var input=input(null,null,0,"0.00",null);service.create(operations,input,"create",UUID.randomUUID());assertThatThrownBy(()->service.create(fixture.f.finance,input,"finance",UUID.randomUUID())).hasMessage("ACCESS_DENIED");fixture.f.jdbc.update("UPDATE commerce.staff_role_assignment SET revoked_at=now() WHERE party_id=? AND role='OPERATIONS'",operations.party());assertThatThrownBy(()->service.create(operations,input,"create",UUID.randomUUID())).hasMessage("ACCESS_DENIED");fixture.f.jdbc.update("UPDATE commerce.staff_role_assignment SET revoked_at=NULL WHERE party_id=? AND role='OPERATIONS'",operations.party());fixture.f.jdbc.update("UPDATE commerce.market_destination SET delivery_enabled=false WHERE market_id=?",fixture.f.market);assertThatThrownBy(()->service.create(operations,input(null,null,1,"0.00",null),"no-route",UUID.randomUUID())).hasMessage("FULFILLMENT_RULE_VIOLATION");assertThatThrownBy(()->resolve(null,null,"0.00")).hasMessage("FULFILLMENT_RULE_VIOLATION");}
 @Test void auditFailureRollsBackRuleAndSuccessfulAcknowledgment(){var f=fixture.f;f.admin.execute("REVOKE INSERT ON commerce.audit_record FROM nigson_commerce_app");try{assertThatThrownBy(()->service.create(operations,input(null,null,0,"0.00",null),"audit",UUID.randomUUID())).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.delivery_rule WHERE market_id=?",Integer.class,f.market)).isZero();assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.idempotency_record WHERE principal_key=? AND operation='API-171' AND request_key='audit' AND state='SUCCEEDED'",Integer.class,operations.party().toString())).isZero();}finally{f.admin.execute("GRANT INSERT ON commerce.audit_record TO nigson_commerce_app");}assertThat(service.create(operations,input(null,null,0,"0.00",null),"audit",UUID.randomUUID()).version()).isZero();}
}
